import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.iWwp2X7T.js";const _=JSON.parse('{"title":"局域网与扫码配对","description":"Mobile Inspector development documentation · 局域网与扫码配对","frontmatter":{"title":"局域网与扫码配对","description":"Mobile Inspector development documentation · 局域网与扫码配对"},"headers":[],"relativePath":"zh/guide/connection-lan.md","filePath":"zh/guide/connection-lan.md"}'),r={name:"zh/guide/connection-lan.md"};function i(s,e,c,l,d,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="局域网与扫码配对" tabindex="-1">局域网与扫码配对 <a class="header-anchor" href="#局域网与扫码配对" aria-label="Permalink to &quot;局域网与扫码配对&quot;">​</a></h1><h2 id="准备网络路径" tabindex="-1">准备网络路径 <a class="header-anchor" href="#准备网络路径" aria-label="Permalink to &quot;准备网络路径&quot;">​</a></h2><p>启动本地查看器，打开 <strong>连接设备</strong>，选择已注册项目或明确的仅本地未分配选项。存在多块网卡时主动选择电脑局域网 IPv4 地址；回环地址不能生成手机二维码。检查同局域网路由与防火墙。</p><h2 id="扫码、确认、记录" tabindex="-1">扫码、确认、记录 <a class="header-anchor" href="#扫码、确认、记录" aria-label="Permalink to &quot;扫码、确认、记录&quot;">​</a></h2><p>点击 <strong>生成连接二维码</strong> 才会打开所选监听。二维码在本地生成，包含 30 分钟上传能力，不能进入截图、日志或提示词。</p><p>内部诊断应用中选择 <strong>扫一扫</strong>，此时才申请摄像头权限。识别后先停止摄像头，再校验与确认。核对地址、有效期和缩略指纹后，点击 <strong>确认配置</strong>。“已配置，发送时验证连接”只表示配置状态，不是到达证明。再独立开始记录，并在查看器核对实际事件。</p><p>权限拒绝或无摄像头时仍可手工粘贴配对 JSON。后台、取消、关闭面板及账号环境变化都会使待处理扫描失效，宿主必须在换号时清除并断开。</p><h2 id="信任与撤销" tabindex="-1">信任与撤销 <a class="header-anchor" href="#信任与撤销" aria-label="Permalink to &quot;信任与撤销&quot;">​</a></h2><p>H5 扫码需要安全上下文；H5、微信和 HarmonyOS 传输需要系统信任的 HTTPS，微信还需域名配置。不能通过安装 CA 或放宽业务 TLS 绕过。原生诊断证书固定是独立策略。</p><p>隐藏二维码或关闭弹窗不撤销能力，需要主动撤销、清除或等待到期。切换地址、项目和传输会移除展示的配对数据。支持的有线 iPhone 流程可使用 <a href="./connection-usb">USB</a>。</p>',10)])])}const u=a(r,[["render",i]]);export{_ as __pageData,u as default};
